namespace ghidra.file.formats.ios.prelink;




using ghidra.app.services;
using ghidra.formats.gfilesystem;
using ghidra.framework.main;
using ghidra.framework.model;
using ghidra.framework.plugintool;
using ghidra.plugin.importer;
using ghidra.program.model.lang;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.program.util;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

public class GFileSystemLoadKernelTask : Task {
	private List<FSRL> fileList;
	private ProgramManager programManager;
	private Project project;

	public GFileSystemLoadKernelTask(Plugin plugin, ProgramManager programManager,
			List<FSRL> fileList) : base("Loading iOS kernel...", true, true, true)
    {
		this.project = plugin.getTool().getProject();
		this.programManager = programManager;
		this.fileList = fileList;
	}

	/* @Override */
	public void run(TaskMonitor monitor) {
		if (fileList.isEmpty()) {
			Msg.showWarn(this, null, "Load Kernel Task Error", "Nothing to do");
			return;
		}
		if (!FSUtilities.isSameFS(fileList)) {
			Msg.showError(this, null, "Load Kernel Task Error",
				"The list of files to import must be from the same filesystem");
			return;
		}
		FSRL firstFSRL = fileList.get(0);
		try
{
    using (RefdFile firstFile = FileSystemService.getInstance().getRefdFile(firstFSRL, monitor))
    {

			GFileSystem fs = firstFile.fsRef.getFilesystem();

			string containerName = fs.getFSRL().getContainer().getName();
			monitor.setMessage("Loading iOS Kernel from " + containerName + "...");
			foreach (FSRL fsrl in fileList) {
				if (monitor.isCancelled()) {
					break;
				}
				GFile file = firstFile.fsRef.getFilesystem().lookup(fsrl.getPath());
				process(file, monitor);

			}
		
    }
}
		catch (Exception e) when (e is UnsupportedOperationException or IOException or CancelledException) {
			Msg.showError(this, null, "Error extracting file", e.getMessage(), e);
		}
	}

	private void process(GFile file, TaskMonitor monitor)
    {

		if (isSpecialDirectory(file)) {
			return;
		}

		if (file.isDirectory() &&
			!((GFileSystemProgramProvider) file.getFilesystem()).canProvideProgram(file)) {
			List<GFile> listing = file.getFilesystem().getListing(file);
			foreach (GFile child in listing) {
				if (monitor.isCancelled()) {
					break;
				}
				process(child, monitor);
			}
		}
		else {
			try {
				loadKext(file, monitor);
			}
			catch (Exception e) {
				Msg.warn(this, "unable to load kext file: " + file.getName(), e);
			}
		}
	}

	private bool isSpecialDirectory(GFile directory2) {
		return false;
	}

	private void loadKext(GFile file, TaskMonitor monitor)
    {
		if (file.getLength() == 0) {
			return;
		}
		if (!file.getName().endsWith(".kext")) {
			return;
		}
		monitor.setMessage("Opening " + file.getName());

		ProjectIndexService projectIndex = ProjectIndexService.getIndexFor(project);
		DomainFile existingDF = projectIndex.findFirstByFSRL(file.getFSRL());
		if (existingDF != null && programManager != null) {
			programManager.openProgram(existingDF);
			return;
		}

		//File cacheFile = FileSystemService.getInstance().getFile(file.getFSRL(), monitor);

		Program program = null;
		if (file.getFilesystem() is GFileSystemProgramProvider programProviderFS) {
			LanguageService languageService = DefaultLanguageService.getLanguageService();

			program = programProviderFS.getProgram(file, languageService, monitor, this);
		}

		if (program != null) {
			try {
				DomainFolder folder = ProjectDataUtils.createDomainFolderPath(
					AppInfo.getActiveProject().getProjectData().getRootFolder(),
					file.getParentFile().getPath());
				string fileName = ProjectDataUtils.getUniqueName(folder, program.getName());
				if (fileName == null) {
					throw new IOException("Unable to find unique name for " + program.getName());
				}

				GhidraProgramUtilities.markProgramAnalyzed(program);

				folder.createFile(fileName, program, monitor);

				programManager.openProgram(program);
			}
			finally {
				program.release(this);
			}
		}
	}
}
